CREATE TABLE IF NOT EXISTS {schema}.sell_now_operations (operation_id {uuid} PRIMARY KEY, sell_order_id {uuid} NOT NULL UNIQUE REFERENCES {schema}.sell_orders(id), market_name {keyed} NOT NULL REFERENCES {schema}.markets(name), seller {uuid} NOT NULL, source_item_blob {blob} NOT NULL, source_fingerprint {keyed} NOT NULL, original_quantity {integer} NOT NULL CHECK (original_quantity > 0), state {status} NOT NULL CHECK (state IN ('RESERVED', 'SETTLING', 'COMPLETED', 'FAILED', 'REVIEW')), failure_detail {body}, created_at {ts} NOT NULL{defaultNow}, updated_at {ts} NOT NULL{defaultNow})
